-- Pierwszy schemat. IF NOT EXISTS pozwala objąć istniejącą lokalną bazę historią migracji.
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(255) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,role VARCHAR(255));
CREATE TABLE IF NOT EXISTS accounts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(255) NOT NULL UNIQUE,account_type VARCHAR(255) NOT NULL,balance NUMERIC(38,2) NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS transactions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,description VARCHAR(255) NOT NULL,amount NUMERIC(38,2) NOT NULL,transaction_date DATE NOT NULL,category VARCHAR(255) NOT NULL,type VARCHAR(255) NOT NULL,account_id BIGINT NOT NULL REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS budgets(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,category VARCHAR(255) NOT NULL,monthly_limit NUMERIC(38,2) NOT NULL);
CREATE TABLE IF NOT EXISTS goals(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(255) NOT NULL,target_amount NUMERIC(38,2) NOT NULL,current_amount NUMERIC(38,2) NOT NULL,target_date DATE);
CREATE TABLE IF NOT EXISTS recurring_payments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(255) NOT NULL,amount NUMERIC(38,2) NOT NULL,frequency VARCHAR(255) NOT NULL,next_due_date DATE NOT NULL);
CREATE TABLE IF NOT EXISTS households(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,household_id BIGINT NOT NULL);
